// entity 1 - the key light. Off to -X and high, so the lit side of a dome has
// one answer and not an argument.
{
"classname" "light"
"origin" "-280 -120 200"
"light" "700"
"_color" "1.0 0.96 0.88"
}
// entity 2 - a dim fill from the far side so the unlit faces are not pure black
{
"classname" "light"
"origin" "280 120 200"
"light" "200"
"_color" "0.7 0.78 1.0"
}
